function JobsPage() {
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('All categories');
  const [type, setType] = useState('All types');
  const [saved, setSaved] = useState<string[]>([]);
  const params = useMemo(() => ({ search: search || undefined, category: category === 'All categories' ? undefined : category, type: type === 'All types' ? undefined : type }), [search, category, type]);
  const query = useListJobs(params, { query: { queryKey: getListJobsQueryKey(params) } });
  const availableJobs = Array.isArray(query.data) && query.data.length > 0 ? query.data : demoJobs;
  const jobs = availableJobs.filter((j) => !category || category === 'All categories' || j.category === category).filter((j) => !type || type === 'All types' || j.type === type).filter((j) => !search || `${j.title} ${j.company} ${j.location}`.toLowerCase().includes(search.toLowerCase()));
  const toggleSave = (id: string) => setSaved((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]);
  return <div className="noise min-h-[100dvh]"><PublicNav /><main className="mx-auto max-w-7xl px-5 py-14 lg:px-8"><div className="max-w-2xl"><p className="text-xs font-bold uppercase tracking-[.18em] text-primary">Open roles</p><h1 className="display-font mt-3 text-6xl leading-none tracking-tight">Find work<br /><em className="text-primary">worth doing.</em></h1><p className="mt-6 text-muted-foreground">A considered collection of roles from teams with something to build.</p></div><div className="mt-12 rounded-2xl border border-border bg-card p-3 shadow-sm"><div className="grid gap-3 md:grid-cols-[1fr_180px_150px_auto]"><label className="flex items-center gap-3 rounded-xl bg-muted px-4"><Search className="size-4 text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Title, company, or location" className="w-full bg-transparent py-3 text-sm outline-none placeholder:text-muted-foreground" data-testid="input-job-search" /></label><select value={category} onChange={(e) => setCategory(e.target.value)} className="rounded-xl bg-muted px-3 py-3 text-sm outline-none" data-testid="select-job-category"><option>All categories</option><option>Design</option><option>Engineering</option><option>Marketing</option><option>Operations</option><option>Research</option></select><select value={type} onChange={(e) => setType(e.target.value)} className="rounded-xl bg-muted px-3 py-3 text-sm outline-none" data-testid="select-job-type"><option>All types</option><option>Full-time</option><option>Contract</option></select><Button variant="dark" onClick={() => { setSearch(search.trim()); }} testId="button-apply-filters"><Filter className="size-4" /> Filter</Button></div></div><div className="mt-9 flex items-center justify-between"><p className="text-sm text-muted-foreground"><span className="font-bold text-foreground">{jobs.length}</span> roles in the loop</p><button className="flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-foreground" data-testid="button-sort-jobs">Newest first <ChevronDown className="size-4" /></button></div><div className="mt-5 grid gap-4">{query.isLoading ? <LoadingState label="Loading roles from the marketplace…" /> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : jobs.length ? jobs.map((job) => <JobCard key={job.id} job={job} saved={saved.includes(job.id)} onSave={toggleSave} />) : <EmptyState title="No roles in this signal yet." detail="Try widening your search or clearing one of the filters." action={<Button variant="outline" onClick={() => { setSearch(''); setCategory('All categories'); setType('All types'); }} className="mt-5" testId="button-clear-filters">Clear filters</Button>} />}</div></main><PublicFooter /></div>;
}

function JobDetail() {
  const { jobId = 'j1' } = useParams<{ jobId: string }>();
  const query = useGetJob(jobId, { query: { queryKey: getGetJobQueryKey(jobId) } });
  const job = query.data ?? demoJobs.find((item) => item.id === jobId) ?? demoJobs[0];
  const [saved, setSaved] = useState(false);
  const [applied, setApplied] = useState(false);
  return <div className="noise min-h-[100dvh]"><PublicNav /><main className="mx-auto max-w-6xl px-5 py-12 lg:px-8"><Link href="/jobs" className="mb-10 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-primary" data-testid="link-back-jobs"><ArrowRight className="size-4 rotate-180" /> Back to roles</Link>{query.isLoading ? <LoadingState /> : query.isError && !job ? <ErrorState onRetry={() => query.refetch()} /> : <div className="grid gap-10 lg:grid-cols-[1fr_320px]"><article><div className="flex gap-4"><Mark tone="coral">{job.logo || job.company.slice(0, 2)}</Mark><div><p className="text-sm font-semibold text-primary">{job.company}</p><h1 className="display-font mt-2 max-w-2xl text-5xl leading-none md:text-6xl">{job.title}</h1><p className="mt-5 text-sm text-muted-foreground">{job.location} <span className="mx-2">·</span> {job.type} <span className="mx-2">·</span> Posted {job.posted}</p></div></div><div className="mt-12 border-t border-border pt-9"><Section title="The role"><p className="leading-7 text-muted-foreground">{job.description}</p></Section><Section title="What you’ll do"><Bullets items={job.responsibilities ?? ['Bring clarity to meaningful work.', 'Partner closely with a thoughtful team.']} /></Section><Section title="What you’ll bring"><Bullets items={job.requirements ?? ['Curiosity, craft, and a bias toward useful outcomes.']} /></Section><Section title="Good to know"><Bullets items={job.benefits ?? ['A team that respects focused work.']} /></Section></div></article><aside><div className="sticky top-28 rounded-2xl border border-border bg-card p-5 shadow-sm"><p className="text-xs font-bold uppercase tracking-[.16em] text-muted-foreground">Compensation</p><p className="mono-font mt-2 text-2xl font-bold">{job.salary}</p><div className="my-6 grid gap-3 border-y border-border py-5 text-sm"><div className="flex justify-between"><span className="text-muted-foreground">Category</span><span className="font-semibold">{job.category}</span></div><div className="flex justify-between"><span className="text-muted-foreground">Work style</span><span className="font-semibold">{job.location.split('·')[1] ?? job.location}</span></div></div><Button onClick={() => setApplied(true)} disabled={applied} className="w-full" testId="button-apply-job">{applied ? <><Check className="size-4" /> Application noted</> : <>Apply to this role <ArrowRight className="size-4" /></>}</Button><Button onClick={() => setSaved(!saved)} variant="outline" className="mt-3 w-full" testId="button-save-detail">{saved ? <><Heart className="size-4 fill-current text-primary" /> Saved</> : <><Heart className="size-4" /> Save for later</>}</Button>{applied && <p className="mt-4 text-center text-xs font-semibold text-secondary-foreground">Nice. Your application is in your demo pipeline.</p>}</div></aside></div>}</main><PublicFooter /></div>;
}

function Section({ title, children }: { title: string; children: ReactNode }) { return <section className="mb-10"><h2 className="mb-4 text-lg font-bold">{title}</h2>{children}</section>; }
function Bullets({ items }: { items: string[] }) { return <ul className="grid gap-3 text-sm leading-6 text-muted-foreground">{items.map((item, i) => <li key={i} className="flex gap-3"><span className="mt-2 size-1.5 shrink-0 rounded-full bg-primary" />{item}</li>)}</ul>; }

function CompaniesPage() {
  const [industry, setIndustry] = useState('All industries');
  const query = useListCompanies(industry === 'All industries' ? undefined : { industry }, { query: { queryKey: getListCompaniesQueryKey(industry === 'All industries' ? undefined : { industry }) } });
  const availableCompanies = Array.isArray(query.data) && query.data.length > 0 ? query.data : demoCompanies;
  const companies = availableCompanies.filter((company) => industry === 'All industries' || company.industry === industry);
  return <div className="noise min-h-[100dvh]"><PublicNav /><main className="mx-auto max-w-7xl px-5 py-14 lg:px-8"><div className="flex flex-wrap items-end justify-between gap-6"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-primary">Company directory</p><h1 className="display-font mt-3 text-6xl leading-none">Meet the<br /><em className="text-primary">good teams.</em></h1><p className="mt-5 max-w-lg text-muted-foreground">Approved companies with open roles, clear intent, and a reason to exist.</p></div><select value={industry} onChange={(e) => setIndustry(e.target.value)} className="rounded-xl border border-border bg-card px-4 py-3 text-sm font-semibold outline-none" data-testid="select-company-industry"><option>All industries</option><option>Technology</option><option>Healthcare</option><option>Consumer</option><option>Climate</option></select></div><div className="mt-12 grid gap-4 md:grid-cols-2">{query.isLoading ? <LoadingState /> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : companies.map((company) => <CompanyCard company={company} key={company.id} />)}</div></main><PublicFooter /></div>;
}
function CompanyCard({ company }: { company: Company }) { return <article className="rounded-2xl border border-border bg-card p-6 transition-all hover:-translate-y-1 hover:border-primary/50" data-testid={`card-company-${company.id}`}><div className="flex items-start justify-between"><div className="flex gap-4"><Mark tone="green">{company.logo || company.name.slice(0, 2)}</Mark><div><h2 className="text-lg font-bold">{company.name}</h2><p className="mt-1 text-sm text-muted-foreground">{company.industry} · {company.location}</p></div></div><MoreHorizontal className="size-5 text-muted-foreground" /></div><p className="mt-6 max-w-lg text-sm leading-6 text-muted-foreground">{company.description}</p><div className="mt-6 flex items-center justify-between border-t border-border pt-4"><span className="text-sm font-semibold">{company.openJobs} open roles</span><Link href="/jobs" className="inline-flex items-center gap-1 text-sm font-bold text-primary hover:gap-2" data-testid={`link-company-jobs-${company.id}`}>View roles <ArrowRight className="size-4" /></Link></div></article>; }

function PricingPage() {
  const [mode, setMode] = useState<'seeker' | 'recruiter'>('seeker');
  const plans = mode === 'seeker' ? [{ name: 'Free signal', price: '$0', description: 'For staying curious.', features: ['Save up to 20 roles', 'One active application board', 'Weekly role digest'] }, { name: 'Focused', price: '$12', description: 'For a move with momentum.', features: ['Unlimited saved roles', 'Application insights', 'Profile signal review', 'Priority role alerts'], featured: true }] : [{ name: 'Starter team', price: '$79', description: 'For a small, sharp hiring team.', features: ['3 active job posts', 'Applicant pipeline', 'Candidate notes'] }, { name: 'Signal team', price: '$199', description: 'For teams hiring with intent.', features: ['Unlimited active roles', 'Collaborative scorecards', 'Hiring analytics', 'Priority support'], featured: true }];
  return <div className="noise min-h-[100dvh]"><PublicNav /><main className="mx-auto max-w-6xl px-5 py-16 lg:px-8"><div className="mx-auto max-w-2xl text-center"><p className="text-xs font-bold uppercase tracking-[.18em] text-primary">Simple plans</p><h1 className="display-font mt-3 text-6xl leading-none">Pay for clarity,<br /><em className="text-primary">not clutter.</em></h1><p className="mt-5 text-muted-foreground">Start free. Upgrade when the timing is right.</p><div className="mx-auto mt-8 inline-flex rounded-xl bg-muted p-1"><button onClick={() => setMode('seeker')} className={`rounded-lg px-5 py-2 text-sm font-semibold ${mode === 'seeker' ? 'bg-card shadow-sm' : 'text-muted-foreground'}`} data-testid="button-pricing-seeker">For seekers</button><button onClick={() => setMode('recruiter')} className={`rounded-lg px-5 py-2 text-sm font-semibold ${mode === 'recruiter' ? 'bg-card shadow-sm' : 'text-muted-foreground'}`} data-testid="button-pricing-recruiter">For recruiters</button></div></div><div className="mx-auto mt-14 grid max-w-4xl gap-5 md:grid-cols-2">{plans.map((plan) => <article key={plan.name} className={`relative rounded-2xl border p-7 ${plan.featured ? 'border-primary bg-foreground text-background shadow-xl' : 'border-border bg-card'}`}>{plan.featured && <span className="absolute right-6 top-6 rounded-full bg-primary px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-primary-foreground">Most useful</span>}<p className={`text-sm font-bold ${plan.featured ? 'text-secondary' : 'text-primary'}`}>{plan.name}</p><p className="mono-font mt-7 text-4xl font-bold">{plan.price}<span className="text-sm font-normal opacity-60"> / month</span></p><p className={`mt-3 text-sm ${plan.featured ? 'text-background/60' : 'text-muted-foreground'}`}>{plan.description}</p><Button href="/auth/register" variant={plan.featured ? 'primary' : 'outline'} className="mt-8 w-full" testId={`link-plan-${plan.name.replaceAll(' ', '-').toLowerCase()}`}>{plan.price === '$0' ? 'Start free' : 'Choose plan'} <ArrowRight className="size-4" /></Button><ul className={`mt-8 grid gap-4 border-t pt-7 text-sm ${plan.featured ? 'border-background/15 text-background/80' : 'border-border text-muted-foreground'}`}>{plan.features.map((feature) => <li key={feature} className="flex gap-3"><Check className="size-4 shrink-0 text-secondary" />{feature}</li>)}</ul></article>)}</div></main><PublicFooter /></div>;
}

function AuthPage({ register = false }: { register?: boolean }) {
  const [role, setRole] = useState<'seeker' | 'recruiter'>('seeker');
  return <div className="noise min-h-[100dvh] bg-foreground text-background"><div className="mx-auto flex min-h-[100dvh] max-w-7xl flex-col px-5 lg:px-8"><div className="flex h-24 items-center"><Logo light /></div><main className="grid flex-1 items-center gap-16 py-12 lg:grid-cols-[.9fr_1.1fr]"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-primary">HireLoop demo access</p><h1 className="display-font mt-4 text-6xl leading-[.92] md:text-7xl">{register ? <>Start with a<br /><em className="text-secondary">clearer signal.</em></> : <>Welcome back<br /><em className="text-secondary">to the loop.</em></>}</h1><p className="mt-6 max-w-md leading-7 text-background/60">{register ? 'Choose the workspace that fits your next move. You can explore the full demo without an account.' : 'This build is set up for exploring the seeker, recruiter, and admin workspaces.'}</p><Link href={register ? '/auth/sign-in' : '/auth/register'} className="mt-8 inline-flex items-center gap-2 text-sm font-bold text-primary hover:gap-3" data-testid="link-auth-switch">{register ? 'Already have a workspace? Sign in' : 'New to HireLoop? Create one'} <ArrowRight className="size-4" /></Link></div><div className="rounded-3xl bg-background p-7 text-foreground shadow-2xl md:p-10"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">{register ? 'Create workspace' : 'Sign in'}</p><h2 className="mt-2 text-2xl font-bold">{register ? 'Pick your path' : 'Use a demo workspace'}</h2></div><span className="grid size-10 place-items-center rounded-xl bg-primary/10 text-primary"><Zap className="size-5" /></span></div>{register && <div className="mt-8 grid grid-cols-2 gap-3"><button onClick={() => setRole('seeker')} className={`rounded-xl border p-4 text-left ${role === 'seeker' ? 'border-primary bg-primary/5' : 'border-border'}`} data-testid="button-role-seeker"><UserRound className="size-5 text-primary" /><p className="mt-3 text-sm font-bold">I’m finding work</p><p className="mt-1 text-xs text-muted-foreground">Build a considered shortlist.</p></button><button onClick={() => setRole('recruiter')} className={`rounded-xl border p-4 text-left ${role === 'recruiter' ? 'border-primary bg-primary/5' : 'border-border'}`} data-testid="button-role-recruiter"><Building2 className="size-5 text-primary" /><p className="mt-3 text-sm font-bold">I’m hiring</p><p className="mt-1 text-xs text-muted-foreground">Meet the right candidates.</p></button></div>}<form onSubmit={(e) => e.preventDefault()} className="mt-8 grid gap-4"><label className="grid gap-2 text-sm font-semibold">Email address<input type="email" placeholder="you@work.com" className="rounded-xl border border-input bg-card px-4 py-3 font-normal outline-none focus:border-primary" data-testid="input-auth-email" /></label>{register && <label className="grid gap-2 text-sm font-semibold">Your name<input placeholder="What should we call you?" className="rounded-xl border border-input bg-card px-4 py-3 font-normal outline-none focus:border-primary" data-testid="input-auth-name" /></label>}<label className="grid gap-2 text-sm font-semibold">Password<input type="password" placeholder="At least 8 characters" className="rounded-xl border border-input bg-card px-4 py-3 font-normal outline-none focus:border-primary" data-testid="input-auth-password" /></label><Button type="submit" href={register ? (role === 'seeker' ? '/dashboard/seeker' : '/dashboard/recruiter') : '/dashboard/seeker'} className="mt-2 w-full" testId="button-auth-submit">{register ? 'Create demo workspace' : 'Continue to demo'} <ArrowRight className="size-4" /></Button></form><p className="mt-5 text-center text-xs text-muted-foreground">No real credentials needed · demo mode</p></div></main></div></div>;
}

const seekerNav = [{ href: '/dashboard/seeker', label: 'Overview', icon: LayoutDashboard }, { href: '/dashboard/seeker/jobs', label: 'Browse jobs', icon: Search }, { href: '/dashboard/seeker/saved', label: 'Saved roles', icon: Heart }, { href: '/dashboard/seeker/applications', label: 'Applications', icon: Layers3 }, { href: '/dashboard/seeker/billing', label: 'Billing', icon: DollarSign }, { href: '/dashboard/seeker/settings', label: 'Settings', icon: Settings }];
const recruiterNav = [{ href: '/dashboard/recruiter', label: 'Overview', icon: LayoutDashboard }, { href: '/dashboard/recruiter/company', label: 'Company profile', icon: Building2 }, { href: '/dashboard/recruiter/jobs', label: 'Manage jobs', icon: BriefcaseBusiness }, { href: '/dashboard/recruiter/billing', label: 'Billing', icon: DollarSign }, { href: '/dashboard/recruiter/settings', label: 'Settings', icon: Settings }];
const adminNav = [{ href: '/dashboard/admin', label: 'Overview', icon: LayoutDashboard }, { href: '/dashboard/admin/users', label: 'Users', icon: UsersRound }, { href: '/dashboard/admin/companies', label: 'Companies', icon: Building2 }, { href: '/dashboard/admin/jobs', label: 'Job moderation', icon: BriefcaseBusiness }, { href: '/dashboard/admin/payments', label: 'Payments', icon: DollarSign }, { href: '/dashboard/admin/settings', label: 'Settings', icon: Settings }];

function DashboardShell({ children, role = 'seeker', title = 'Overview' }: { children: ReactNode; role?: 'seeker' | 'recruiter' | 'admin'; title?: string }) {
  const [mobile, setMobile] = useState(false);
  const nav = role === 'seeker' ? seekerNav : role === 'recruiter' ? recruiterNav : adminNav;
  const health = useHealthCheck({ query: { queryKey: getHealthCheckQueryKey() } });
  return <div className="flex min-h-[100dvh] bg-background"><aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-sidebar text-sidebar-foreground transition-transform lg:static lg:translate-x-0 ${mobile ? 'translate-x-0' : '-translate-x-full'}`}><div className="flex h-full flex-col p-5"><Logo light /><div className="mt-12 flex-1"><p className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-sidebar-foreground/45">{role} workspace</p><nav className="grid gap-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} className="flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-medium text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground" data-testid={`link-sidebar-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon className="size-[17px]" />{label}</Link>)}{role === 'recruiter' && <Link href="/dashboard/jobs/j1/applicants" className="flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-medium text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground" data-testid="link-sidebar-applicants"><UsersRound className="size-[17px]" />Applicant pipeline</Link>}</nav></div><div className="border-t border-sidebar-border pt-4"><div className="mb-4 flex items-center gap-3 px-2"><span className="grid size-9 place-items-center rounded-full bg-secondary text-xs font-bold text-secondary-foreground">{role === 'admin' ? 'AD' : role === 'recruiter' ? 'AR' : 'MC'}</span><div><p className="text-sm font-semibold">{role === 'admin' ? 'Avery Diaz' : role === 'recruiter' ? 'Ari Rivers' : 'Maya Chen'}</p><p className="text-[11px] text-sidebar-foreground/45">{role === 'seeker' ? 'Product designer' : role === 'recruiter' ? 'Arcade Labs' : 'Platform admin'}</p></div></div><Link href="/" className="flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-sidebar-foreground/55 hover:bg-sidebar-accent hover:text-sidebar-foreground" data-testid="link-sidebar-exit"><LogOut className="size-4" />Exit workspace</Link></div></div></aside>{mobile && <button className="fixed inset-0 z-40 bg-foreground/30 lg:hidden" onClick={() => setMobile(false)} aria-label="Close navigation" data-testid="button-close-navigation" />}<div className="min-w-0 flex-1"><header className="sticky top-0 z-30 flex h-[72px] items-center justify-between border-b border-border bg-background/90 px-5 backdrop-blur-xl lg:px-10"><div className="flex items-center gap-3"><button onClick={() => setMobile(true)} className="rounded-lg p-2 lg:hidden" data-testid="button-open-navigation"><Menu className="size-5" /></button><div><p className="text-lg font-bold">{title}</p><p className="hidden text-xs text-muted-foreground sm:block">{role === 'seeker' ? 'Keep the good work moving.' : role === 'recruiter' ? 'Hiring with signal, not volume.' : 'A clear view of the platform.'}</p></div></div><div className="flex items-center gap-3"><span className="hidden items-center gap-2 rounded-full bg-secondary/60 px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider text-secondary-foreground sm:flex"><span className="size-1.5 rounded-full bg-secondary-foreground" />{health.data?.status ?? 'Demo mode'}</span><button className="rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-foreground" aria-label="Notifications" data-testid="button-notifications"><Bell className="size-[18px]" /></button><button className="grid size-9 place-items-center rounded-full bg-primary/15 text-xs font-bold text-primary" data-testid="button-profile-menu">{role === 'admin' ? 'AD' : role === 'recruiter' ? 'AR' : 'MC'}</button></div></header><main className="dashboard-grid min-h-[calc(100dvh-72px)] p-5 lg:p-10">{children}</main></div></div>;
}

function StatTile({ label, value, detail, tone = 'default' }: { label: string; value: string | number; detail?: string; tone?: 'default' | 'coral' | 'green' }) { return <div className={`rounded-2xl border p-5 ${tone === 'coral' ? 'border-primary/30 bg-primary/10' : tone === 'green' ? 'border-secondary/60 bg-secondary/40' : 'border-border bg-card'}`}><p className="text-xs font-semibold text-muted-foreground">{label}</p><p className="mono-font mt-4 text-3xl font-bold tracking-tight" data-testid={`text-stat-${label.toLowerCase().replaceAll(' ', '-')}`}>{value}</p>{detail && <p className="mt-2 text-xs text-muted-foreground">{detail}</p>}</div>; }
function ActivityList({ items }: { items: Activity[] }) { return <div className="divide-y divide-border">{items.map((item) => <div className="flex gap-3 py-4 first:pt-0 last:pb-0" key={item.id} data-testid={`activity-${item.id}`}><span className={`mt-1 grid size-7 shrink-0 place-items-center rounded-full ${item.tone === 'positive' ? 'bg-secondary text-secondary-foreground' : item.tone === 'accent' ? 'bg-accent/30 text-foreground' : 'bg-muted text-muted-foreground'}`}><Check className="size-3.5" /></span><div className="min-w-0"><p className="text-sm font-semibold">{item.title}</p><p className="mt-1 truncate text-xs text-muted-foreground">{item.detail}</p><p className="mt-2 text-[10px] uppercase tracking-wider text-muted-foreground">{item.time}</p></div></div>)}</div>; }
function MiniChart({ data, color = 'bg-primary' }: { data: ChartDatum[]; color?: string }) { const max = Math.max(...data.map((item) => item.value), 1); return <div className="flex h-44 items-end gap-3">{data.map((item) => <div className="group flex flex-1 flex-col items-center gap-2" key={item.label}><span className="text-[10px] font-bold opacity-0 transition-opacity group-hover:opacity-100">{item.value}</span><div className={`w-full rounded-t-md ${color}`} style={{ height: `${Math.max(10, (item.value / max) * 125)}px` }} /><span className="text-[10px] text-muted-foreground">{item.label}</span></div>)}</div>; }
function DashboardHeading({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail: string; action?: ReactNode }) { return <div className="flex flex-wrap items-end justify-between gap-5"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-primary">{eyebrow}</p><h1 className="mt-2 text-3xl font-bold tracking-tight lg:text-4xl">{title}</h1><p className="mt-2 text-sm text-muted-foreground">{detail}</p></div>{action}</div>; }

function SeekerOverview() {
  const query = useGetSeekerDashboard({ query: { queryKey: getGetSeekerDashboardQueryKey() } }); const data = query.data ?? fallbackSeeker;
  return <DashboardShell><DashboardHeading eyebrow="Monday, 14 October" title="Your next move, in view." detail="Here’s what’s happening across your search." action={<Button href="/dashboard/seeker/jobs" testId="link-dashboard-browse">Browse roles <ArrowRight className="size-4" /></Button>} />{query.isLoading ? <LoadingState /> : <><div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatTile label="Saved roles" value={data.savedJobs} detail="3 added this week" tone="coral" /><StatTile label="Applications" value={data.applications} detail="2 awaiting a reply" /><StatTile label="Interviews" value={data.interviews} detail="Next one Thursday" tone="green" /><StatTile label="Offers" value={data.offers} detail="Keep going" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><div><h2 className="font-bold">Application pulse</h2><p className="mt-1 text-xs text-muted-foreground">Your pipeline, at a glance.</p></div><Link href="/dashboard/seeker/applications" className="text-xs font-bold text-primary" data-testid="link-view-applications">View pipeline <ArrowRight className="ml-1 inline size-3" /></Link></div><div className="mt-7"><MiniChart data={data.applicationBreakdown} /></div></section><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><h2 className="font-bold">Recent activity</h2><Clock3 className="size-4 text-muted-foreground" /></div><div className="mt-6"><ActivityList items={data.recentActivity} /></div></section></div><section className="mt-5 rounded-2xl border border-border bg-foreground p-6 text-background"><div className="flex flex-wrap items-center justify-between gap-5"><div className="flex items-center gap-4"><span className="grid size-12 place-items-center rounded-2xl bg-primary text-primary-foreground"><Target className="size-6" /></span><div><p className="font-bold">Profile strength: {data.profileCompletion}%</p><p className="mt-1 text-sm text-background/55">A little more context can make the right role find you.</p></div></div><Button href="/dashboard/seeker/settings" variant="primary" testId="link-complete-profile">Complete profile <ArrowRight className="size-4" /></Button></div></section></>}</DashboardShell>;
}

function SeekerJobs({ savedOnly = false }: { savedOnly?: boolean }) {
  const [saved, setSaved] = useState<string[]>(['j2', 'j4']); const query = useListJobs(undefined, { query: { queryKey: getListJobsQueryKey() } }); const availableJobs = Array.isArray(query.data) && query.data.length > 0 ? query.data : demoJobs; const jobs = availableJobs.filter((job) => !savedOnly || saved.includes(job.id)); const toggle = (id: string) => setSaved((list) => list.includes(id) ? list.filter((item) => item !== id) : [...list, id]);
  return <DashboardShell title={savedOnly ? 'Saved roles' : 'Browse jobs'}><DashboardHeading eyebrow={savedOnly ? 'Your shortlist' : 'Marketplace'} title={savedOnly ? 'Roles worth another look.' : 'Find your next good fit.'} detail={savedOnly ? 'A smaller list makes better decisions.' : 'Search the marketplace without losing your train of thought.'} action={!savedOnly && <Button href="/dashboard/seeker/saved" variant="outline" testId="link-view-saved"><Heart className="size-4" /> View saved</Button>} /><div className="mt-8 grid gap-4 lg:grid-cols-2">{query.isLoading ? <LoadingState /> : jobs.length ? jobs.map((job) => <JobCard key={job.id} job={job} saved={saved.includes(job.id)} onSave={toggle} />) : <EmptyState title="Your shortlist is waiting." detail="Save a role from Browse jobs and it will appear here." action={<Button href="/dashboard/seeker/jobs" className="mt-5" testId="link-empty-browse">Browse roles</Button>} />}</div></DashboardShell>;
}

function ApplicationsPage() { const stages = [['Applied', ['Product Designer, Growth', 'Senior Brand Strategist']], ['Screening', ['Staff Software Engineer']], ['Interview', ['Operations Lead']], ['Offer', ['Research Fellow, Climate']]]; return <DashboardShell title="Applications"><DashboardHeading eyebrow="Your pipeline" title="Keep the loop moving." detail="Every application has a next step. You do not have to guess it." /><div className="mt-8 grid gap-4 xl:grid-cols-4">{stages.map(([stage, roles], i) => <section className="rounded-2xl border border-border bg-card p-4" key={String(stage)}><div className="flex items-center justify-between"><h2 className="text-sm font-bold">{stage}</h2><span className="grid size-6 place-items-center rounded-full bg-muted text-[10px] font-bold">{(roles as string[]).length}</span></div><div className="mt-4 grid gap-3">{(roles as string[]).map((role) => <div className="rounded-xl border border-border bg-background p-4" key={role}><span className={`mb-4 block size-2 rounded-full ${i === 0 ? 'bg-muted-foreground' : i === 1 ? 'bg-accent' : i === 2 ? 'bg-primary' : 'bg-secondary-foreground'}`} /><p className="text-sm font-semibold leading-5">{role}</p><p className="mt-2 text-xs text-muted-foreground">{i === 0 ? 'Waiting for review' : i === 1 ? 'In consideration' : i === 2 ? 'Next step scheduled' : 'A very good sign'}</p></div>)}</div></section>)}</div></DashboardShell>; }
function SimpleWorkspacePage({ role, title, eyebrow, detail, children }: { role: 'seeker' | 'recruiter' | 'admin'; title: string; eyebrow: string; detail: string; children: ReactNode }) { return <DashboardShell role={role} title={title}><DashboardHeading eyebrow={eyebrow} title={title} detail={detail} />{children}</DashboardShell>; }
function BillingPage({ role }: { role: 'seeker' | 'recruiter' }) { return <SimpleWorkspacePage role={role} title="Billing" eyebrow="Plan & usage" detail="Keep your workspace working the way you need it to."><div className="mt-8 grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><section className="rounded-2xl border border-primary/30 bg-primary/10 p-7"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-primary">Current plan</p><h2 className="mt-3 text-3xl font-bold">{role === 'seeker' ? 'Focused' : 'Signal team'}</h2><p className="mt-2 text-sm text-muted-foreground">Your next renewal is 14 November 2025.</p></div><Sparkles className="size-6 text-primary" /></div><div className="mt-8 flex gap-3"><Button testId="button-manage-plan">Manage plan</Button><Button variant="outline" testId="button-view-invoices">View invoices</Button></div></section><section className="rounded-2xl border border-border bg-card p-7"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">This month</p><div className="mt-5 flex items-end justify-between"><span className="mono-font text-4xl font-bold">{role === 'seeker' ? '12' : '11'}</span><span className="text-sm text-muted-foreground">of {role === 'seeker' ? '∞ saved roles' : '∞ active roles'}</span></div><div className="mt-5 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full w-[68%] rounded-full bg-primary" /></div><p className="mt-4 text-xs text-muted-foreground">You’re using your workspace at a healthy pace.</p></section></div></SimpleWorkspacePage>; }
function SettingsPage({ role }: { role: 'seeker' | 'recruiter' | 'admin' }) { const [saved, setSaved] = useState(false); return <SimpleWorkspacePage role={role} title="Settings" eyebrow="Workspace settings" detail="Small details, set up once."><div className="mt-8 max-w-3xl rounded-2xl border border-border bg-card p-6 md:p-8"><div className="flex items-center gap-4 border-b border-border pb-6"><span className="grid size-14 place-items-center rounded-full bg-secondary text-lg font-bold text-secondary-foreground">{role === 'admin' ? 'AD' : role === 'recruiter' ? 'AR' : 'MC'}</span><div><h2 className="font-bold">{role === 'admin' ? 'Avery Diaz' : role === 'recruiter' ? 'Ari Rivers' : 'Maya Chen'}</h2><p className="text-sm text-muted-foreground">{role === 'recruiter' ? 'ari@arcadelabs.com' : role === 'admin' ? 'avery@hireloop.com' : 'maya@work.com'}</p></div><Button variant="outline" className="ml-auto hidden sm:inline-flex" testId="button-change-avatar">Change photo</Button></div><form onSubmit={(e) => { e.preventDefault(); setSaved(true); }} className="mt-7 grid gap-5"><div className="grid gap-5 sm:grid-cols-2"><label className="grid gap-2 text-sm font-semibold">First name<input defaultValue={role === 'admin' ? 'Avery' : role === 'recruiter' ? 'Ari' : 'Maya'} className="rounded-xl border border-input bg-background px-4 py-3 font-normal outline-none focus:border-primary" data-testid="input-settings-first-name" /></label><label className="grid gap-2 text-sm font-semibold">Last name<input defaultValue={role === 'admin' ? 'Diaz' : role === 'recruiter' ? 'Rivers' : 'Chen'} className="rounded-xl border border-input bg-background px-4 py-3 font-normal outline-none focus:border-primary" data-testid="input-settings-last-name" /></label></div><label className="grid gap-2 text-sm font-semibold">About you<textarea defaultValue="I like useful products, generous teams, and work that leaves things better than it found them." className="min-h-28 rounded-xl border border-input bg-background px-4 py-3 font-normal outline-none focus:border-primary" data-testid="textarea-settings-about" /></label><div className="flex items-center justify-between border-t border-border pt-5"><span className={`text-xs font-semibold text-secondary-foreground ${saved ? '' : 'invisible'}`} data-testid="status-settings-saved"><Check className="mr-1 inline size-3" />Changes saved</span><Button type="submit" testId="button-save-settings">Save changes</Button></div></form></div></SimpleWorkspacePage>; }

function RecruiterOverview() { const query = useGetRecruiterDashboard({ query: { queryKey: getGetRecruiterDashboardQueryKey() } }); const data = query.data ?? fallbackRecruiter; return <DashboardShell role="recruiter"><DashboardHeading eyebrow="Arcade Labs · Monday" title="Build the right team." detail="Your hiring signal, in one place." action={<Button href="/dashboard/recruiter/jobs/new" testId="link-post-job"><Plus className="size-4" /> Post a role</Button>} /><div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatTile label="Active roles" value={data.activeJobs} detail={`${data.totalJobPosts} total posted`} tone="coral" /><StatTile label="Applicants" value={data.totalApplicants} detail="Across all roles" /><StatTile label="Roles closed" value={data.jobsClosed} detail="A good hiring pace" tone="green" /><StatTile label="Avg. time to signal" value="4.2d" detail="Down 18% this month" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><div><h2 className="font-bold">Applicant flow</h2><p className="mt-1 text-xs text-muted-foreground">How candidates are moving through.</p></div><BarChart3 className="size-4 text-muted-foreground" /></div><div className="mt-7"><MiniChart data={data.applicantBreakdown} color="bg-secondary-foreground" /></div></section><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><h2 className="font-bold">Latest activity</h2><Link href="/dashboard/jobs/j1/applicants" className="text-xs font-bold text-primary" data-testid="link-recruiter-applicants">View applicants</Link></div><div className="mt-6"><ActivityList items={data.recentApplications} /></div></section></div></DashboardShell>; }
function RecruiterJobs() { const [published, setPublished] = useState<string[]>(['j1', 'j2', 'j3']); return <SimpleWorkspacePage role="recruiter" title="Manage jobs" eyebrow="Your roles" detail="Keep each opening clear, current, and easy to act on."><div className="mt-8 overflow-hidden rounded-2xl border border-border bg-card"><div className="flex items-center justify-between border-b border-border p-5"><div className="flex items-center gap-2 text-sm text-muted-foreground"><SlidersHorizontal className="size-4" /> {published.length} active roles</div><Button href="/dashboard/recruiter/jobs/new" testId="link-new-job"><Plus className="size-4" /> Post a role</Button></div>{demoJobs.slice(0, 4).map((job) => <div className="flex flex-wrap items-center justify-between gap-4 border-b border-border p-5 last:border-0" key={job.id} data-testid={`row-recruiter-job-${job.id}`}><div className="flex items-center gap-3"><Mark>{job.logo}</Mark><div><Link href={`/jobs/${job.id}`} className="font-semibold hover:text-primary" data-testid={`link-recruiter-job-${job.id}`}>{job.title}</Link><p className="mt-1 text-xs text-muted-foreground">{job.location} · 24 applicants</p></div></div><div className="flex items-center gap-3"><span className={`rounded-full px-3 py-1 text-[10px] font-bold uppercase tracking-wider ${published.includes(job.id) ? 'bg-secondary text-secondary-foreground' : 'bg-muted text-muted-foreground'}`}>{published.includes(job.id) ? 'Live' : 'Paused'}</span><button onClick={() => setPublished((list) => list.includes(job.id) ? list.filter((id) => id !== job.id) : [...list, job.id])} className="rounded-lg p-2 text-muted-foreground hover:bg-muted" aria-label="Toggle job status" data-testid={`button-toggle-job-${job.id}`}><MoreHorizontal className="size-4" /></button><Link href={`/dashboard/jobs/${job.id}/applicants`} className="rounded-lg border border-border px-3 py-2 text-xs font-semibold hover:border-primary hover:text-primary" data-testid={`link-applicants-${job.id}`}>Applicants</Link></div></div>)}</div></SimpleWorkspacePage>; }
function NewJobPage() { const [posted, setPosted] = useState(false); return <SimpleWorkspacePage role="recruiter" title="Post a role" eyebrow="New opening" detail="A clear brief attracts the people you actually want to meet."><form onSubmit={(e) => { e.preventDefault(); setPosted(true); }} className="mt-8 max-w-3xl rounded-2xl border border-border bg-card p-6 md:p-8"><div className="grid gap-5"><label className="grid gap-2 text-sm font-semibold">Role title<input placeholder="e.g. Staff Product Designer" required className="rounded-xl border border-input bg-background px-4 py-3 font-normal outline-none focus:border-primary" data-testid="input-new-job-title" /></label><div className="grid gap-5 sm:grid-cols-2"><label className="grid gap-2 text-sm font-semibold">Location<input placeholder="Remote · US" className="rounded-xl border border-input bg-background px-4 py-3 font-normal outline-none focus:border-primary" data-testid="input-new-job-location" /></label><label className="grid gap-2 text-sm font-semibold">Category<select className="rounded-xl border border-input bg-background px-4 py-3 font-normal outline-none focus:border-primary" data-testid="select-new-job-category"><option>Design</option><option>Engineering</option><option>Marketing</option><option>Operations</option></select></label></div><label className="grid gap-2 text-sm font-semibold">Salary range<input placeholder="$130k–$165k" className="rounded-xl border border-input bg-background px-4 py-3 font-normal outline-none focus:border-primary" data-testid="input-new-job-salary" /></label><label className="grid gap-2 text-sm font-semibold">The role<textarea placeholder="What will this person make possible?" className="min-h-32 rounded-xl border border-input bg-background px-4 py-3 font-normal outline-none focus:border-primary" data-testid="textarea-new-job-description" /></label><div className="flex items-center justify-between border-t border-border pt-5"><span className={`text-xs font-semibold text-secondary-foreground ${posted ? '' : 'invisible'}`} data-testid="status-job-posted"><Check className="mr-1 inline size-3" />Draft posted to your workspace</span><Button type="submit" testId="button-submit-new-job">{posted ? 'Posted' : 'Post role'} <ArrowRight className="size-4" /></Button></div></div></form></SimpleWorkspacePage>; }
function ApplicantsPage() { const [stage, setStage] = useState('All'); const people = [{ name: 'Maya Chen', role: 'Staff Software Engineer', stage: 'Reviewing', initials: 'MC' }, { name: 'Jordan Bell', role: 'Product Designer', stage: 'Interview', initials: 'JB' }, { name: 'Leo Martin', role: 'Operations Lead', stage: 'New', initials: 'LM' }, { name: 'Sam Rivera', role: 'Product Designer', stage: 'Offer', initials: 'SR' }].filter((p) => stage === 'All' || p.stage === stage); return <SimpleWorkspacePage role="recruiter" title="Applicant pipeline" eyebrow="Product Designer, Growth" detail="A shortlist, not a queue."><div className="mt-8 flex gap-2 overflow-x-auto pb-1">{['All', 'New', 'Reviewing', 'Interview', 'Offer'].map((item) => <button onClick={() => setStage(item)} key={item} className={`whitespace-nowrap rounded-full px-4 py-2 text-xs font-bold ${stage === item ? 'bg-foreground text-background' : 'border border-border bg-card text-muted-foreground'}`} data-testid={`button-filter-applicants-${item.toLowerCase()}`}>{item}</button>)}</div><div className="mt-4 overflow-hidden rounded-2xl border border-border bg-card">{people.map((person) => <div className="flex flex-wrap items-center justify-between gap-4 border-b border-border p-5 last:border-0" key={person.name} data-testid={`row-applicant-${person.initials}`}><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-full bg-accent/30 text-xs font-bold">{person.initials}</span><div><p className="text-sm font-bold">{person.name}</p><p className="mt-1 text-xs text-muted-foreground">{person.role}</p></div></div><div className="flex items-center gap-4"><span className="rounded-full bg-muted px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider">{person.stage}</span><button onClick={() => setStage(person.stage)} className="rounded-lg p-2 text-muted-foreground hover:bg-muted" aria-label={`Filter to ${person.stage} applicants`} data-testid={`button-applicant-menu-${person.initials}`}><MoreHorizontal className="size-4" /></button></div></div>)}</div></SimpleWorkspacePage>; }

function AdminOverview() { const query = useGetAdminDashboard({ query: { queryKey: getGetAdminDashboardQueryKey() } }); const data = query.data ?? fallbackAdmin; return <DashboardShell role="admin"><DashboardHeading eyebrow="Platform pulse" title="Keep the loop healthy." detail="A clear view of marketplace trust and momentum." /><div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><StatTile label="Total users" value={data.totalUsers.toLocaleString()} /><StatTile label="Recruiters" value={data.totalRecruiters.toLocaleString()} /><StatTile label="Companies" value={data.totalCompanies} tone="green" /><StatTile label="Active jobs" value={data.totalJobs} tone="coral" /><StatTile label="Revenue" value={data.platformRevenue} /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1fr_1fr]"><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><div><h2 className="font-bold">New users</h2><p className="mt-1 text-xs text-muted-foreground">The last five days.</p></div><TrendingUp className="size-4 text-secondary-foreground" /></div><div className="mt-7"><MiniChart data={data.newUsers} color="bg-primary" /></div></section><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><div><h2 className="font-bold">Jobs by category</h2><p className="mt-1 text-xs text-muted-foreground">Where demand is clustering.</p></div><BarChart3 className="size-4 text-muted-foreground" /></div><div className="mt-7 grid gap-4">{data.jobPostsByCategory.map((item) => <div key={item.label}><div className="mb-2 flex justify-between text-xs"><span className="font-semibold">{item.label}</span><span className="text-muted-foreground">{item.value}</span></div><div className="h-2 rounded-full bg-muted"><div className="h-full rounded-full bg-secondary-foreground" style={{ width: `${Math.min(100, item.value / 4)}%` }} /></div></div>)}</div></section></div></DashboardShell>; }
function AdminTable({ kind }: { kind: 'users' | 'companies' | 'jobs' | 'payments' }) { const rows = kind === 'users' ? [['Maya Chen', 'Seeker', 'Active'], ['Ari Rivers', 'Recruiter', 'Active'], ['Jordan Bell', 'Seeker', 'Review'], ['Avery Diaz', 'Admin', 'Active']] : kind === 'companies' ? [['Arcade Labs', 'Technology', 'Approved'], ['Northstar Health', 'Healthcare', 'Approved'], ['Morrow', 'Consumer', 'Pending'], ['Field Notes', 'Climate', 'Approved']] : kind === 'jobs' ? [['Product Designer, Growth', 'Arcade Labs', 'Live'], ['Staff Software Engineer', 'Northstar Health', 'Live'], ['Senior Brand Strategist', 'Morrow', 'Flagged'], ['Operations Lead', 'Field Notes', 'Live']] : [['INV-1048', 'Arcade Labs', '$1,200', 'Paid'], ['INV-1047', 'Northstar Health', '$2,400', 'Paid'], ['INV-1046', 'Morrow', '$900', 'Pending'], ['INV-1045', 'Field Notes', '$600', 'Paid']]; const headers = kind === 'payments' ? ['Invoice', 'Account', 'Amount', 'Status'] : kind === 'users' ? ['Name', 'Role', 'Status'] : ['Name', kind === 'companies' ? 'Industry' : 'Company', 'Status']; return <SimpleWorkspacePage role="admin" title={kind === 'users' ? 'Users' : kind === 'companies' ? 'Companies' : kind === 'jobs' ? 'Job moderation' : 'Payments'} eyebrow="Admin workspace" detail="Make the high-signal call."><div className="mt-8 overflow-hidden rounded-2xl border border-border bg-card"><div className="flex items-center justify-between border-b border-border p-5"><div className="flex items-center gap-2 text-sm text-muted-foreground"><Search className="size-4" /> Search {kind}</div><Button variant="outline" testId={`button-filter-${kind}`}><Filter className="size-4" /> Filter</Button></div><div className="overflow-x-auto"><table className="w-full min-w-[540px] text-left text-sm"><thead className="bg-muted/60 text-xs uppercase tracking-wider text-muted-foreground"><tr>{headers.map((head) => <th className="px-5 py-4 font-bold" key={head}>{head}</th>)}<th className="px-5 py-4" /></tr></thead><tbody>{rows.map((row, i) => <tr className="border-t border-border" key={i} data-testid={`row-admin-${kind}-${i}`}>{row.map((cell, j) => <td className="px-5 py-4" key={j}><span className={j === row.length - 1 ? 'rounded-full bg-secondary/70 px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider' : i === 0 ? 'font-semibold' : 'text-muted-foreground'}>{cell}</span></td>)}<td className="px-5 py-4 text-right"><button className="rounded-lg p-2 text-muted-foreground hover:bg-muted" aria-label="Open row actions" data-testid={`button-admin-actions-${kind}-${i}`}><MoreHorizontal className="size-4" /></button></td></tr>)}</tbody></table></div></div></SimpleWorkspacePage>; }

function AppRouter() { return <ErrorBoundary><Switch><Route path="/" component={Home} /><Route path="/jobs" component={JobsPage} /><Route path="/jobs/:jobId" component={JobDetail} /><Route path="/companies" component={CompaniesPage} /><Route path="/pricing" component={PricingPage} /><Route path="/auth/sign-in"><AuthPage /></Route><Route path="/auth/register"><AuthPage register /></Route><Route path="/dashboard/seeker" component={SeekerOverview} /><Route path="/dashboard/seeker/jobs"><SeekerJobs /></Route><Route path="/dashboard/seeker/saved"><SeekerJobs savedOnly /></Route><Route path="/dashboard/seeker/applications" component={ApplicationsPage} /><Route path="/dashboard/seeker/billing"><BillingPage role="seeker" /></Route><Route path="/dashboard/seeker/settings"><SettingsPage role="seeker" /></Route><Route path="/dashboard/recruiter" component={RecruiterOverview} /><Route path="/dashboard/recruiter/company"><SimpleWorkspacePage role="recruiter" title="Company profile" eyebrow="Arcade Labs" detail="The story behind the roles."><div className="mt-8 max-w-3xl rounded-2xl border border-border bg-card p-7"><div className="flex items-center gap-4"><Mark tone="green">AL</Mark><div><h2 className="text-xl font-bold">Arcade Labs</h2><p className="mt-1 text-sm text-muted-foreground">Technology · New York, NY · 51–200 people</p></div><Button variant="outline" className="ml-auto" testId="button-edit-company">Edit profile</Button></div><p className="mt-8 border-t border-border pt-7 leading-7 text-muted-foreground">We build software that gives ambitious teams more room to think. Our best work happens at the intersection of a sharp question and a generous team.</p></div></SimpleWorkspacePage></Route><Route path="/dashboard/recruiter/jobs" component={RecruiterJobs} /><Route path="/dashboard/recruiter/jobs/new" component={NewJobPage} /><Route path="/dashboard/jobs/:jobId/applicants" component={ApplicantsPage} /><Route path="/dashboard/recruiter/billing"><BillingPage role="recruiter" /></Route><Route path="/dashboard/recruiter/settings"><SettingsPage role="recruiter" /></Route><Route path="/dashboard/admin" component={AdminOverview} /><Route path="/dashboard/admin/users"><AdminTable kind="users" /></Route><Route path="/dashboard/admin/companies"><AdminTable kind="companies" /></Route><Route path="/dashboard/admin/jobs"><AdminTable kind="jobs" /></Route><Route path="/dashboard/admin/payments"><AdminTable kind="payments" /></Route><Route path="/dashboard/admin/settings"><SettingsPage role="admin" /></Route><Route component={NotFound} /></Switch></ErrorBoundary>; }

function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><AppRouter /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }

export default App;